mapper.select:
select #{uid} uid,s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name,s.top_number, s.top_type,  s.signing_data,  s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.state,s.file,s.open_file,s.mid_file,s.over_file
from  sci_horizontal_apply_vertical s left join sys_user u on  s.user_id=u.user_id
                                      left join sys_dept d on u.dept_id = d.dept_id
                                      left join sys_dept p on d.parent_id =p.dept_id
where  s.state in (1,2,3,4,5,6,7,99)
 and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
 and user_name like concat('%', #{userName}, '%')
 and top_name like concat('%', #{topName}, '%')
 and d.dept_name like concat('%', #{dname}, '%')
 or top_number =  #{topNumber}
 and state = #{state}
${params.dataScope}
order by s.createtime desc

mapper.update:
update sci_horizontal_apply_vertical
user_id = #{userId}, top_name = #{topName}, top_number = #{topNumber}, top_type = #{topType}, signing_data = #{signingData}, validity_data = #{validityData}, first_person_id = #{firstPersonId}, second_person_id = #{secondPersonId}, third_person_id = #{thirdPersonId}, fourth_person_id = #{fourthPersonId}, amount = #{amount}, file = #{file}, open_file = #{openfile}, mid_file = #{midfile}, over_file = #{overfile}, state = #{state},
where id = #{id}
